<template><section class="section-card"><h2 class="section-title">Deliver Benefits</h2><div class="section-body"><el-alert title="Uses the published campaign and current published Additional suit." type="info" :closable="false"/><el-form label-position="top" class="compact-form"><el-form-item label="Recipients"><el-select v-model="userIds" multiple filterable style="width:100%"><el-option v-for="user in users" :key="user.id" :label="user.name" :value="user.id"/></el-select></el-form-item><el-form-item v-if="campaign.published.kind==='compensation'" label="Case reference"><el-input v-model.trim="caseRef" maxlength="100"/></el-form-item><el-form-item label="Reason"><el-input v-model.trim="reason" type="textarea" maxlength="500"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!userIds.length || reason.length<3 || (campaign.published.kind==='compensation' && !caseRef)" @click="deliver">Review &amp; Deliver</el-button></el-form><p class="field-help">Campaign: once per user. Compensation: once per case/user. Duplicate recipients are skipped without extra grants.</p><el-table v-if="result" :data="result.results" row-key="userId"><el-table-column prop="name" label="Recipient"/><el-table-column prop="status" label="Result"/></el-table></div></section></template>
<script>
import { listUsers,runCampaign,requestKey } from '@/api/commerce'
export default {props:{campaign:{type:Object,required:true}},data(){return{users:[],userIds:[],reason:'',caseRef:'',busy:false,result:null,attempt:null}},async created(){this.users=await listUsers()},methods:{async deliver(){try{await this.$confirm(`Deliver published v${this.campaign.publishedVersion} to ${this.userIds.length} users? Extra benefit: ${this.campaign.published.creditAmount} Credits, ${this.campaign.published.creditValidityDays} days. Any selected suit has its own benefit.`, 'Deliver Benefits',{confirmButtonText:'Deliver',cancelButtonText:'Cancel'})}catch(_){return}this.busy=true;const input={campaignId:this.campaign.id,userIds:this.userIds,reason:this.reason,caseRef:this.caseRef};const fingerprint=JSON.stringify(input);if(!this.attempt||this.attempt.fingerprint!==fingerprint)this.attempt={fingerprint,key:requestKey()};try{this.result=await runCampaign({...input,requestKey:this.attempt.key});this.$message.success('Delivery recorded.');this.$emit('changed')}catch(_){}finally{this.busy=false}}}}
</script>
